  ["CANAL DO YOUTUBE"] = "YOUTUBE CHANNEL",
  ["Canal do YouTube"] = "YouTube channel",
  ["Este projeto é uma iniciativa independente, criada por fãs e para fãs do console R36S. Não possui vínculo oficial com os fabricantes do dispositivo, com o PortMaster ou com os desenvolvedores dos jogos e ports disponibilizados por terceiros."] = "This project is an independent initiative, created by fans and for fans of the R36S console. It has no official affiliation with the device manufacturers, with PortMaster or with the developers of the games and ports provided by third parties.",
  ["FEITO PELA COMUNIDADE, PARA A COMUNIDADE!"] = "MADE BY THE COMMUNITY, FOR THE COMMUNITY!",
  ["Fechar"] = "Close",
  ["Fonte online"] = "Online source",
  ["Mais do que uma plataforma para descobrir e baixar ports de jogos, o projeto busca reunir em um único ambiente recursos que facilitem o uso, o gerenciamento, a manutenção, a personalização e o aproveitamento do console."] = "More than a platform for discovering and downloading game ports, the project aims to bring together in a single environment resources that make it easier to use, manage, maintain, customize and get the most out of the console.",
  ["Não foi possível gerar o QR Code."] = "Could not generate the QR Code.",
  ["Não há navegador disponível neste console. Aponte a câmera do celular para o QR Code ou digite o endereço no navegador do celular ou computador."] = "There is no browser available on this console. Point your phone's camera at the QR Code or type the address in the browser of your phone or computer.",
  ["Não nos responsabilizamos pela criação, funcionamento, conteúdo ou distribuição de projetos de terceiros. Respeite as licenças e os direitos autorais aplicáveis a cada projeto."] = "We are not responsible for the creation, operation, content or distribution of third-party projects. Respect the licenses and copyrights that apply to each project.",
  ["Não somos proprietários dos jogos, ports ou demais conteúdos de terceiros. Seus direitos pertencem aos respectivos desenvolvedores e detentores de propriedade intelectual."] = "We do not own the games, ports or other third-party content. Their rights belong to their respective developers and intellectual property holders.",
  ["O R36S PORT HUB está em constante evolução, com a intenção de incorporar novos recursos e funcionalidades que tornem o console ainda mais versátil."] = "R36S PORT HUB is constantly evolving, with the intention of adding new features and functions that make the console even more versatile.",
  ["O R36S PORT HUB é gratuito e feito por fãs, nas horas vagas. "] = "R36S PORT HUB is free and made by fans in their spare time. ",
  ["O R36S PORT HUB é um projeto independente desenvolvido para ampliar as possibilidades do console portátil R36S."] = "R36S PORT HUB is an independent project developed to expand the possibilities of the R36S handheld console.",
  ["Obrigado pelo apoio!"] = "Thank you for your support!",
