  ["Ajuda"] = "Help",
  ["Atalho: leia o QR Code da tela Servidor FTP com a câmera. Ele abre o endereço ftp://; o aplicativo pede usuário e senha."] = "Shortcut: scan the QR Code on the FTP server screen with the camera. It opens the ftp:// address; the app asks for the username and password.",
