  ["Conecte o celular Android na MESMA rede Wi-Fi do console (dados móveis não funcionam)."] = "Connect the Android phone to the SAME Wi-Fi network as the console (mobile data does not work).",
  ["Conecte o computador (Windows ou Linux) na MESMA rede do console, por Wi-Fi ou cabo no mesmo roteador."] = "Connect the computer (Windows or Linux) to the SAME network as the console, via Wi-Fi or cable on the same router.",
