  ["O pacote é baixado, conferido e extraído; nenhum script dele é executado. Depois, reinicie a lista (Sair > Reiniciar lista) para o PortMaster aparecer em Ferramentas."] = "The package is downloaded, checked and extracted; none of its scripts are run. Then restart the list (Exit > Restart list) so PortMaster shows up in Tools.",
  ["Atualizar o PortMaster?"] = "Update PortMaster?",
  ["versão desconhecida"] = "unknown version",
  ["  (estável)"] = "  (stable)",
  ["Preservados: ports, saves, configurações (config/), temas, autoinstall e %d runtime(s) em libs/. Os arquivos que mudarem ganham backup antes; se algo falhar, o backup é restaurado e conferido."] = "Kept: ports, saves, settings (config/), themes, autoinstall and %d runtime(s) in libs/. Files that change are backed up first; if something fails, the backup is restored and checked.",
  ["Baixar o pacote de referência?"] = "Download the reference package?",
  ["Para reparar, o hub baixa o pacote oficial da versão instalada (%s, %s, conferência: %s) e compara arquivo por arquivo (md5).\n\nNada é alterado antes de você ver a lista do que será restaurado."] = "To repair, the hub downloads the official package of the installed version (%s, %s, check: %s) and compares file by file (md5).\n\nNothing is changed before you see the list of what will be restored.",
  ["BAIXAR E COMPARAR"] = "DOWNLOAD AND COMPARE",
  ["Reparar o PortMaster?"] = "Repair PortMaster?",
  ["Ausentes: %d   •   Diferentes do oficial: %d"] = "Missing: %d   •   Different from official: %d",
  ["As permissões também serão corrigidas."] = "Permissions will also be fixed.",
  ["Os arquivos diferentes ganham backup antes. Configurações, ports e runtimes não são tocados."] = "Different files are backed up first. Settings, ports and runtimes are not touched.",
  ["REPARAR"] = "REPAIR",
  ["O PortMaster não foi encontrado neste console."] = "PortMaster was not found on this console.",
  ["Pastas verificadas: /opt/system/Tools/PortMaster, /roms/ports/PortMaster, /opt/tools/PortMaster e a pasta informada pelo PortMaster."] = "Folders checked: /opt/system/Tools/PortMaster, /roms/ports/PortMaster, /opt/tools/PortMaster and the folder given by PortMaster.",
