  ["Método: md5 de %d arquivos comparados com o pacote oficial desta versão (baixado e conferido)."] = "Method: md5 of %d files compared with the official package of this version (downloaded and checked).",
  ["Método: arquivos essenciais. Sem referência completa desta versão, arquivos alterados não são detectados (use X: verificação completa)."] = "Method: essential files. Without a full reference for this version, changed files are not detected (use X: full check).",
