  ["Valor informado pelo próprio sistema (time_to_full)."] = "Value reported by the system itself (time_to_full).",
  ["Calculado com a corrente real (%d mA) e a capacidade real (%d mAh, %s). Acima de 80%% a corrente cai e a carga fica mais lenta: isso já está considerado."] = "Calculated with the real current (%d mA) and the real capacity (%d mAh, %s). Above 80%% the current drops and charging slows down: this is already taken into account.",
  ["ESTIMATIVA APROXIMADA: o sistema não informa corrente e capacidade, então o cálculo usa a velocidade observada (%.1f%% por hora em %d min). A fase final mais lenta já está considerada."] = "ROUGH ESTIMATE: the system does not report current and capacity, so the calculation uses the observed speed (%.1f%% per hour over %d min). The slower final stage is already taken into account.",
  ["Medindo a velocidade de carga..."] = "Measuring the charging speed...",
  ["O sistema não informa corrente e capacidade. Deixe esta tela aberta com o carregador conectado: a estimativa aproximada aparece depois que a carga subir pelo menos 2%% (mínimo 2 min). Observado até agora: +%d%% em %d min."] = "The system does not report current and capacity. Keep this screen open with the charger connected: the rough estimate appears after the charge goes up at least 2%% (2 min minimum). Observed so far: +%d%% in %d min.",
  ["Não foi possível calcular o tempo de carregamento com precisão. Verifique se o carregador está conectado e tente novamente."] = "The charging time could not be calculated accurately. Check that the charger is connected and try again.",
  ["Nível, estado, tensão, corrente e capacidade que o sistema informa, e o tempo estimado para a carga completa. Somente leitura."] = "Level, state, voltage, current and capacity reported by the system, and the estimated time to a full charge. Read only.",
  ["carregando"] = "charging",
