  ["A lista de downloads finalizados será apagada. Os ports instalados não são alterados."] = "The list of finished downloads will be deleted. Installed ports are not changed.",
  ["A pasta do hub não está em ports/r36sporthub: atualizações bloqueadas."] = "The hub folder is not in ports/r36sporthub: updates blocked.",
  ["A senha aparece em Configurar servidor FTP. Ela nunca vai para os registros nem para as exportações."] = "The password is shown in Configure FTP server. It never goes into logs or exports.",
  ["Abrir Favoritos"] = "Open Favorites",
  ["Abrir Meus Ports"] = "Open My Ports",
  ["Ao pedir ajuda, envie o relatório exportado e o arquivo de erro (pasta logs). Eles trazem a versão, o sistema e as últimas linhas do registro, sem senhas."] = "When asking for help, send the exported report and the error file (logs folder). They include the version, the system and the last log lines, without passwords.",
  ["Apaga só a lista de downloads finalizados. Ports instalados e arquivos não são tocados."] = "Deletes only the list of finished downloads. Installed ports and files are not touched.",
  ["Apaga só as capas guardadas e baixa de novo quando aparecerem (útil se uma capa foi trocada no servidor). Precisa de internet."] = "Deletes only the stored covers and downloads them again when they appear (useful if a cover was changed on the server). Needs internet.",
