  ["Versões instaladas, data, origem e resultado."] = "Installed versions, date, source and result.",
  ["Volta ao Tema Padrão, ao tamanho de texto padrão e liga as animações. Brilho e idioma não mudam."] = "Goes back to the Default Theme and the default text size, and turns animations on. Brightness and language do not change.",
  ["Volta ao padrão a tela inicial, a saída, as notificações, o som, a música, as animações, o tamanho do texto, a ordenação das listas e a gravação. Idioma, tema, brilho, FTP, favoritos e históricos não mudam."] = "Restores the defaults for the start screen, exit, notifications, sound, music, animations, text size, list sorting and recording. Language, theme, brightness, FTP, favorites and histories do not change.",
  ["Volta para uma versão anterior a partir dos backups feitos antes de cada atualização."] = "Goes back to a previous version using the backups made before each update.",
