  ["Capas dos ports guardadas no console. A apaga só esse cache: as capas são baixadas de novo quando aparecerem (precisa de internet). Ports instalados e o catálogo não mudam."] = "Port covers stored on the console. A clears only this cache: covers are downloaded again when they appear (needs internet). Installed ports and the catalog do not change.",
