  ["Mensagens rápidas que aparecem por alguns segundos. Janelas de confirmação sempre aparecem."] = "Quick messages shown for a few seconds. Confirmation windows always appear.",
  ["Modelo, processador, tela, sistema, data e hora."] = "Model, processor, screen, system, date and time.",
