  ["Navegue pelo cartão SD: copiar, recortar, colar, excluir e extrair arquivos ZIP, RAR, 7z e TAR."] = "Browse the SD card: copy, cut, paste, delete and extract ZIP, RAR, 7z and TAR files.",
  ["Não dá para colar dentro da pasta do R36S PORT HUB."] = "You cannot paste inside the R36S PORT HUB folder.",
