  ["Abre na hora o desenho do controle: cada botão acende quando apertado, os analógicos mostram posição, alcance e deriva. Segure B por 3 segundos para voltar."] = "Opens the controller drawing right away: each button lights up when pressed, the sticks show position, range and drift. Hold B for 3 seconds to go back.",
  ["Abre o R36S Analog Tester (por LagdoLira): analógicos, zona morta, deriva e todos os botões, com relatório salvo. O hub fecha durante o teste e volta sozinho quando você sair."] = "Opens R36S Analog Tester (by LagdoLira): sticks, dead zone, drift and every button, with a saved report. The hub closes during the test and reopens by itself when you exit.",
