  ["\n\nDá para editar pelo FTP, pelo Gerenciador de arquivos do PC ou com o cartão SD no PC."] = "\n\nYou can edit it over FTP, from a PC file manager or with the SD card on a PC.",
  ["\n\nPara adicionar uma senha, escreva uma por linha no arquivo:\n"] = "\n\nTo add a password, write one per line in the file:\n",
  ["\nArquivo em %d partes: todas serão usadas, como no PC."] = "\nArchive in %d parts: all of them will be used, like on a PC.",
  ["\nSuas senhas: %d"] = "\nYour passwords: %d",
  [" • %d PARTES"] = " • %d PARTS",
  ["%d do hub + %d suas"] = "%d from the hub + %d yours",
  ["Capa do pacote aplicada: "] = "Cover from the package applied: ",
  ["O arquivo está protegido por senha e nenhuma das senhas salvas funcionou. Adicione a senha certa no arquivo senhas.txt da pasta do hub (Configurações > Downloads > Senhas de arquivos compactados) e tente de novo."] = "The file is password-protected and none of the saved passwords worked. Add the right password to senhas.txt in the hub folder (Settings > Downloads > Archive passwords) and try again.",
  ["PARTE %d"] = "PART %d",
  ["Senhas de arquivos compactados"] = "Archive passwords",
  ["Senhas do hub: "] = "Hub passwords: ",
  ["\n\nSenhas dos grupos e arquivos em partes são tratados sozinhos. Depois de cada instalação bem-sucedida, o arquivo compactado é excluído."] = "\n\nGroup passwords and multi-part archives are handled automatically. After each successful install, the archive is deleted.",
  [" (ex.: baixados do Telegram)."] = " (e.g. downloaded from Telegram).",
  ["%d arquivo(s) prontos para instalar"] = "%d file(s) ready to install",
